  let root = null;

  function insert(val) {
    function rec(node) {
      if (!node) {
        node = { value: val, left: null, right: null };
        return node;
      }
      if (val < node.value) {
        node.left = rec(node.left);
      } else if (val > node.value) {
        node.right = rec(node.right);
      }
      return node;
    }
    root = rec(root);
