function egalProfond(a, b) {
  // Strict equality covers primitives and identical object references
  if (a === b) return true;

  // Handle null/undefined (including the case where only one is null)
  if (a == null || b == null) return a === b;

  // Special handling for NaN (NaN !== NaN)
  if (typeof a === 'number' && typeof b === 'number' && isNaN(a) && isNaN(b)) return true;

  // If either is not an object, they can't be deeply equal
  if (typeof a !== 'object' || typeof b !== 'object') return false;

  // Handle Date objects
  if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();

  // Handle RegExp objects
  if (a instanceof RegExp && b instanceof RegExp) return a.source === b.source && a.flags === b.flags;

  // Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!egalProfond(a[i], b[i])) return false;
    }
    return true;
  }

  // Plain objects (including other objects)
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    if (!keysB.includes(key) || !egalProfond(a[key], b[key])) return false;
  }
  return true;
}
