function creerBST() {
  // Node constructor
  function Node(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }

  // Insert helper
  function insert(node, val) {
    if (node === null) return new Node(val);
    if (val < node.value) node.left = insert(node.left, val);
    else if (val > node.value) node.right = insert(node.right, val);
    return node;
  }

  // Search helper
  function contains(node, val) {
    if (node === null) return false;
    if (val === node.value) return true;
    return val < node.value ? contains(node.left, val) : contains(node.right, val);
  }

  // Return the API
  return {
    insert: function (val) {
      this.root = insert(this.root, val);
    },
    contains: function (val) {
      return contains(this.root, val);
    },
    // optional: expose root for debugging
    _root: function () { return this.root; }
  };
}
