function creerFilePriorite() {
  const heap = [];

  function _heapifyUp(index) {
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (heap[parent].priorite <= heap[index].priorite) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  function _heapifyDown(index) {
    const n = heap.length;
    while (true) {
      let smallest = index;
      const left = index * 2 + 1;
      const right = index * 2 + 2;
      if (left < n && heap[left].priorite < heap[smallest].priorite) smallest = left;
      if (right < n && heap[right].priorite < heap[smallest].priorite) smallest = right;
      if (smallest === index) break;
      [heap[smallest], heap[index]] = [heap[index], heap[smallest]];
      index = smallest;
    }
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      _heapifyUp(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      const min = heap[0];
      const last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        _heapifyDown(0);
      }
      return min;
    },
    taille() {
      return heap.length;
    }
  };
}
