function creerSubject() {
  const subscribers = [];
  let closed = false;

  return {
    next(value) {
      if (closed) return;
      subscribers.forEach(s => s.next(value));
    },
    error(err) {
      if (closed) return;
      subscribers.forEach(s => s.error(err));
      closed = true;
    },
    complete() {
      if (closed) return;
      subscribers.forEach(s => s.complete());
      closed = true;
    },
    subscribe(observer) {
      const observerCopy = {
        next: observer.next || (() => {}),
        error: observer.error || (() => {}),
        complete: observer.complete || (() => {})
      };
      subscribers.push(observerCopy);
      return {
        unsubscribe: () => {
          const idx = subscribers.indexOf(observerCopy);
          if (idx > -1) subscribers.splice(idx, 1);
        }
      };
    }
  };
}
