function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED';
  let failures = 0;
  let timeoutId = null;

  const open = () => {
    state = 'OPEN';
    timeoutId = setTimeout(() => {
      state = 'HALF_OPEN';
    }, delaiResetMs);
  };

  const close = () => {
    state = 'CLOSED';
    failures = 0;
    clearTimeout(timeoutId);
  };

  return async function(...args) {
    if (state === 'OPEN') {
      return Promise.reject(new Error('Circuit breaker OPEN'));
    }
    try {
      const result = await fn.apply(this, args);
      if (state === 'CLOSED') failures = 0;
      if (state === 'HALF_OPEN') close();
      return result;
    } catch (err) {
      if (state === 'CLOSED') {
        failures++;
        if (failures >= seuil) open();
      } else if (state === 'HALF_OPEN') {
        open();
      }
      throw err;
    }
  };
}
```

